async function api(path, options) { const response=await fetch(`${API}${path}`,options); const data=await response.json(); if(!response.ok) throw new Error(data.error||"请求失败"); return data; }
function arrayBufferToBase64(buffer){const bytes=new Uint8Array(buffer);let binary="";for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(binary);}

function ReportContent({text}) {
  const lines=String(text||"").split(/\r?\n/); const blocks=[]; let index=0;
  const cells=line=>line.trim().replace(/^\||\|$/g,"").split("|").map(value=>value.trim());
  const separator=line=>/^\s*\|?(?:\s*:?-{3,}:?\s*\|)+\s*:?-{3,}:?\s*\|?\s*$/.test(line);
  while(index<lines.length){
    const line=lines[index];
    if(line.trim().startsWith("|")&&index+1<lines.length&&separator(lines[index+1])){
      const header=cells(line); const rows=[]; index+=2;
      while(index<lines.length&&lines[index].trim().startsWith("|")){rows.push(cells(lines[index]));index+=1;}
      blocks.push(<div className="report-table-wrap" key={`table-${index}`}><table className="report-table"><thead><tr>{header.map((value,column)=><th key={column}>{value}</th>)}</tr></thead><tbody>{rows.map((row,rowIndex)=><tr key={rowIndex}>{header.map((_,column)=><td className={/^[-+]?\d/.test(row[column]||"")?"numeric":""} key={column}>{row[column]||"—"}</td>)}</tr>)}</tbody></table></div>);continue;
    }
    if(!line.trim()){blocks.push(<div className="report-gap" key={`gap-${index}`}></div>);index+=1;continue;}
    if(line.startsWith("### "))blocks.push(<h4 key={index}>{line.slice(4)}</h4>);
    else if(line.startsWith("## "))blocks.push(<h3 key={index}>{line.slice(3)}</h3>);
    else if(line.startsWith("# "))blocks.push(<h2 key={index}>{line.slice(2)}</h2>);
    else if(line.startsWith("- "))blocks.push(<p className="report-list-item" key={index}>{line.slice(2)}</p>);
    else blocks.push(<p key={index}>{line}</p>);
    index+=1;
  }
  return <div className="report-content">{blocks}</div>;
}

function ScaleControl({value,onChange,compact=false}) {
  return <div className={`scale-control ${compact?"compact":""}`} role="group" aria-label="界面大小"><span>显示</span>{uiScaleOptions.map(option=><button type="button" className={value===option.value?"active":""} aria-pressed={value===option.value} onClick={()=>onChange(option.value)} key={option.value}>{option.label}</button>)}</div>;
}

