  function chooseFile(event){const file=event.target.files?.[0];if(!file)return;if(file.size>5*1024*1024){setError("数据文件不能超过 5 MB");return;}const extension=file.name.split(".").pop()?.toLowerCase();if(!["csv","xlsx"].includes(extension)){setError("仅支持 CSV 或 XLSX 文件");return;}const reader=new FileReader();reader.onload=async()=>{const next=extension==="xlsx"?{xlsxBase64:arrayBufferToBase64(reader.result),csvText:"",filename:file.name}:{csvText:String(reader.result),xlsxBase64:"",filename:file.name};resetRecoveryHistory();setXlsxBase64(next.xlsxBase64);setCsvText(next.csvText);setFilename(next.filename);await inspectUpload(next);};reader.onerror=()=>setError("无法读取文件");if(extension==="xlsx")reader.readAsArrayBuffer(file);else reader.readAsText(file,"utf-8");}
